if (off.length) setTimeout(() => {
showToast('🔒', `Снято не по уровню: ${off.length}`);
logLoot(`🔒 Снято — не по уровню: ${off.join(', ')}. Вещи в сумке, наденете, когда дорастёте.`, 'log-info');
}, 1800);
