if (cloud && typeof migrateDustScale === 'function') migrateDustScale(cloud.items);
const local = loadStorage();
const localAt = getStorageLocalUpdatedAt();
let synced = null;
try { synced = localStorage.getItem(STORAGE_SYNCED_KEY); } catch (e) {}
