__refineHistory.unshift({
type: 'reset',
itemName,
oldLevel,
});
if (__refineHistory.length > 20) __refineHistory.length = 20;
showToast('🗑', `Подгонка сброшена: ${itemName} +${oldLevel} → +0`);
logLoot(`🗑 Подгонка сброшена: ${itemName} +${oldLevel} → +0`, 'log-info');
